src=[
 Q('۱. در فرض A قطره‌ای و B ذرهٔ معلق، تهویه، رسوب، ماسک و مواجههٔ نزدیک را مقایسه کنید.','طبق پاسخنامه: تهویهٔ ضعیف بیشتر B را مطرح می‌کند؛ رسیدن به آلوئول در مدل B؛ برای A ماسک جراحی و B نوع N95 در پاسخ آمده؛ مواجههٔ نزدیک‌تر با A برجسته است. حدود عددی و کفایت حفاظت، فرض آموزشی‌اند.',['چهار محور','پاسخ متناسب با فرض','فرض سؤال'],[3,5],'پرسش ۱ منبع؛ چهار بخش'),
 Q('۲. برای دوز کم فردبه‌فرد، انتقال از خزنده/ماکیان، فلور روده و کلنی صورتی مثال بزنید.','به ترتیب پاسخنامه: شیگلا؛ سالمونلا؛ اشریشیا کلی/انتروباکتر/کلبسیلا؛ همان سه نام برای کلنی صورتی در مثال‌ها.',['چهار معیار','مثال متناسب'],[3,5],'پرسش ۲ منبع؛ چهار بخش'),
 Q('۳. آنتی‌ژن حرکت، Vi، جایگاه O و نام آنتی‌ژن کپسولی چیست؟','H آنتی‌ژن تاژکی است؛ Vi آنتی‌ژن کپسولیِ شناخته‌شده در سالمونلا تایفی است؛ O بخش پلی‌ساکاریدی LPS و K آنتی‌ژن کپسولی است.',['H و تاژک','Vi و سالمونلا تایفی','O و LPS','K و کپسول'],[3,5],'پرسش ۳ جزوه'),
 Q('۴. مراحل بیماری‌زایی را نام ببرید.','اتصال و استقرار، اثر فرآورده‌های التهابی، تهاجم بافتی، فرار از دفاع و انتشار با علامت؛ این توالیِ پاسخنامه است و برای همهٔ گونه‌ها شکل یکسان الزامی ندارد.',['اتصال','اثر','تهاجم','دفاع','انتشار'],[3,5],'پرسش ۴ منبع'),
 Q('۵. شکل، کدام عامل را نشان می‌دهد؟','کلید پاسخ، کاتالاز است: کاهش اثر پراکسید هیدروژن در فشار اکسیداتیو فاگوسیت؛ شکل را اثبات حذف همهٔ مواد مانند HOCl ندان.',['کاتالاز','پراکسید','بقا'],[3,5],'پرسش تصویری ۵ منبع'),
 Q('۶. بخش‌های AB، نوع ۳ و عامل تحریک گستردهٔ T را توضیح دهید.','A فعال، B اتصال؛ سامانهٔ نوع ۳ انتقال پروتئین اثرگذار و تغییر پیام‌رسانی سلول؛ سوپرآنتی‌ژن پاسخ بخش فعال‌سازی گستردهٔ T است.',['A/B','سامانه','سوپرآنتی‌ژن'],[3,5,6],'پرسش ۶ منبع؛ سه بخش'),
 Q('۷. تب تیفوئید چگونه توضیح داده شده است؟','ورود با آب/غذا، عبور روده‌ای با سلول M، بقا در ماکروفاژ، گسترش با خون و لنف و التهاب سیستمیک، تب و بزرگی کبد و طحال.',['ورود','M','ماکروفاژ','انتشار','علامت'],[4,6],'پرسش ۷ منبع'),
 Q('۸. چرا پاکت پریودنتال خطر باکتریمی را افزایش می‌دهد؟ دو گروه پرخطر نام ببرید.','آسیب و خونریزی سد در حضور جمعیت میکروبی، مسیر ورود به خون را مطرح می‌کند. دو نمونه: پیوند/شیمی‌درمانی و دریچهٔ مصنوعی؛ دیابت و بیماری شدید نیز در فهرست‌اند.',['سد','جمعیت','دو گروه'],[4,6],'پرسش ۸ منبع'),
 Q('۹. عفونت‌های دهانی و راه انتقال مرتبط را نام ببرید.','آبسه، عفونت کانال نکروزه، استوماتیت پروتز و زخم در نقص ایمنی در پاسخنامه‌اند؛ مسیر مدفوعی–دهانی و استقرار در دهان ذکر شده است. نقش این خانواده در همهٔ نمونه‌ها قطعی و انحصاری نیست.',['چهار نمونه','راه منبع','عدم تعمیم'],[4,6],'پرسش ۹ منبع'),
 Q('۱۰. مدیریت مصرف، توجه به نشانه‌های سیستمیک و روش کم‌آسیب چرا مهم‌اند؟','مدیریت مصرف انتخاب/انتشار مقاومت را محدود می‌کند؛ نشانه‌های دهانی ممکن است زمینهٔ سیستمیک را مطرح کنند ولی اختصاصی نیستند؛ کاهش آسیب سد می‌تواند ورود به خون را کاهش دهد.',['مقاومت','زمینه','سد'],[4,6],'پرسش ۱۰ منبع؛ سه بخش')]
mixed=[Q('یک پاسخ خوب تشریحی چگونه از فهرست نام‌ها فراتر می‌رود؟','معیار را تعریف می‌کنم، نام یا مرحله را می‌نویسم، سپس رابطهٔ علت و پیامد و قیدهای مسئله را اضافه می‌کنم؛ نمونه: اندازهٔ ذره، ماندگاری و اهمیت تهویه در فرض سؤال.',['تعریف','رابطه','قید'],[3,5]),Q('آنتی‌ژن، آنزیم و سامانهٔ ترشحی را با مثال تفکیک کنید.','H یک آنتی‌ژن تاژکی، کاتالاز آنزیم حفاظتی و نوع ۳ سامانهٔ انتقال پروتئین اثرگذار است؛ این‌ها یک دستهٔ ساختاری یکسان نیستند.',['سه مفهوم','مثال'],[3,5])]
